import {
  BooleanInput,
  coerceBooleanProperty,
  coerceNumberProperty,
  NumberInput,
} from '@angular/cdk/coercion';
import { BreakpointObserver } from '@angular/cdk/layout';
import { NgClass, NgFor, NgIf, NgSwitch, NgSwitchCase } from '@angular/common';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  HostBinding,
  inject,
  Input,
  OnChanges,
  OnInit,
  SimpleChanges,
  ViewEncapsulation,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { isPresent } from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { thickCheck } from '@questrade/allspark-icons/icons';
import { takeUntil } from 'rxjs';
import { QProgressBarSize } from './types/progress-bar-size.type';
import { QProgressBarVariant } from './types/progress-bar-variant.type';

@Component({
  imports: [NgIf, NgSwitch, NgSwitchCase, NgFor, NgClass, QIconComponent],
  providers: [QDestroyService],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-progress-bar',
  templateUrl: './progress-bar.component.html',
  styleUrls: ['./progress-bar.component.scss'],
})
export class QProgressBarComponent implements OnInit, OnChanges {
  @Input() variant: QProgressBarVariant = 'standard';
  @Input() size: QProgressBarSize = 'default';
  @Input() circularProgressLabel = '';
  @Input() selectedState: BooleanInput = false;
  @Input() segmentInReviewIndex: number | null = null;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-progress-bar';

  @Input() get segments(): number {
    return this._segments;
  }
  set segments(value: NumberInput) {
    this._segments = Math.max(
      this._minSegments,
      Math.min(this._maxSegments, coerceNumberProperty(value)),
    );
  }

  @Input() get progress(): number {
    return this._progress;
  }
  set progress(value: NumberInput) {
    this._progress = Math.max(
      this._minProgress,
      Math.min(this._maxProgress, coerceNumberProperty(value)),
    );
  }

  @HostBinding('class') get hostClasses(): string {
    return ['q-progress-bar', `q-progress-bar--${this.size}`].join(' ');
  }

  // This value is not in pixels, it's based on the coordinate system of the SVG viewBox.
  _circularStrokeWidth = 11;
  _pathString = '';
  _progressCirclePath = { strokeDasharray: '' };
  _progressTrailPath = { strokeDasharray: '' };
  _showSuccess = false;
  _segmentPercents: number[] = [];
  _segmentsInReview: number[] = [];

  private readonly _minSegments = 2;
  private readonly _maxSegments = 50;
  private readonly _minProgress = 0;
  private readonly _maxProgress = 100;
  private readonly _strokeWidthSmallView = 15;
  private readonly _strokeWidthDefault = 11;
  private _segments = this._minSegments;
  private _progress = this._minProgress;
  private readonly _iconRegistryService = inject(QIconRegistryService);
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _cdr = inject(ChangeDetectorRef);

  ngOnInit(): void {
    this._registerIcons();
    this._setBreakpointObserver();
  }

  ngOnChanges(changes: SimpleChanges): void {
    const { progress, selectedState, segmentInReviewIndex } = changes;

    if (this.segments && this.variant === 'steps') {
      if (segmentInReviewIndex) {
        this.segmentInReviewIndex = coerceNumberProperty(segmentInReviewIndex.currentValue, null);
      }

      this._setSegments();
    }

    if (progress && this.variant === 'circular') {
      this._setCirclePaths();
    }

    if (selectedState && this.variant === 'circular') {
      this.selectedState = coerceBooleanProperty(
        selectedState.currentValue && this.progress === 100,
      );

      if (!selectedState.currentValue && this.progress === 100) {
        this._showSuccess = true;
      }
    }
  }

  _setSegments(): void {
    const segmentWidth = 100 / this.segments;
    const filledSegments = Math.floor(this.progress / segmentWidth);
    const remainingProgress = this.progress - filledSegments * segmentWidth;
    const partialSegmentWidth = remainingProgress / segmentWidth;

    this._segmentPercents = Array.from({ length: this.segments }, (_, index) =>
      index < filledSegments ? 100 : index === filledSegments ? partialSegmentWidth * 100 : 0,
    );

    if (isPresent(this.segmentInReviewIndex)) {
      const segmentsInReview = this._segmentPercents.reduce(
        (accumulator: number[], currentValue: number, currentIndex: number) => {
          if (currentValue > 0) {
            if (currentIndex === this.segmentInReviewIndex && currentValue === 100) {
              accumulator.push(currentIndex);
            } else if (currentIndex > (this.segmentInReviewIndex as number)) {
              accumulator.push(currentIndex);
            }
          }
          return accumulator;
        },
        [],
      );

      this._segmentsInReview = segmentsInReview;
    }
  }

  _isSegmentInReview(index: number): boolean {
    return this._segmentsInReview.some((value) => value === index);
  }

  _setCirclePaths(): void {
    const radius = 50 - this._circularStrokeWidth / 2;
    const len = Math.PI * 2 * radius;
    const endPositionY = radius * -2;

    this._pathString = `M 50,50 m 0,${-radius} a ${radius},${radius} 0 1 1 0,${-endPositionY} a ${radius},${radius} 0 1 1 -0,${endPositionY}`;

    this._progressTrailPath = { strokeDasharray: `${len - 0}px ${len}px` };

    this._progressCirclePath = {
      strokeDasharray: `${((this.progress || 0) / 100) * (len - 0)}px ${len}px`,
    };

    this._showSuccess = this.progress === 100 && !this.selectedState;
  }

  get inProgress(): boolean {
    return this.progress > 0 && this.progress < 100;
  }

  private _setBreakpointObserver(): void {
    this._breakpointObserver
      .observe(['(max-width: 1019px)'])
      .pipe(takeUntil(this._destroy$))
      .subscribe((result) => {
        if (this.variant === 'circular') {
          this._circularStrokeWidth = result.matches
            ? this._strokeWidthSmallView
            : this._strokeWidthDefault;
          this._setCirclePaths();
          this._cdr.markForCheck();
        }
      });
  }

  private _registerIcons(): void {
    this._iconRegistryService.registerIcon(thickCheck);
  }
}
